"""
export_source_md.py - dump every generator source file into one markdown
document, for sharing or reviewing the code without a checkout.

    python tools/export_source_md.py

Writes SOURCE_CODE_SOCIAL.md next to the project root (git-ignored).
"""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "SOURCE_CODE_SOCIAL.md"


def main() -> int:
    parts = [
        "# Social Media Content Calendar & Analytics Planner - Source Code\n",
        "\nGenerated by tools/export_source_md.py. Do not edit by hand.\n",
    ]
    files = sorted(ROOT.glob("*.py"))
    files += sorted((ROOT / "social_media_spreadsheet").glob("*.py"))
    files += sorted((ROOT / "social_media_spreadsheet" / "sheets").glob("*.py"))
    files += sorted((ROOT / "tools").glob("*.py"))
    for path in files:
        if path.name == OUT.name:
            continue
        rel = path.relative_to(ROOT)
        parts.append(f"\n## `{rel}`\n\n```python\n")
        parts.append(path.read_text())
        parts.append("\n```\n")
    OUT.write_text("".join(parts))
    print(f"{OUT.name}: {len(files)} files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
